CREATE TABLE schema_migration(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL,app_build TEXT NOT NULL,checksum TEXT NOT NULL) STRICT;
CREATE TABLE setting(key TEXT PRIMARY KEY,value_json TEXT NOT NULL CHECK(json_valid(value_json)),revision INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE secret(key TEXT PRIMARY KEY,encrypted_blob BLOB NOT NULL,protection TEXT NOT NULL CHECK(protection='DPAPI_USER'),updated_at TEXT NOT NULL) STRICT;
CREATE TABLE operation(id TEXT PRIMARY KEY,type TEXT NOT NULL,state TEXT NOT NULL,started_at TEXT NOT NULL,heartbeat_at TEXT NOT NULL,finished_at TEXT,progress_current INTEGER,progress_total INTEGER,safe_error_json TEXT,correlation_id TEXT NOT NULL,recovery_json TEXT NOT NULL DEFAULT '{}') STRICT;
CREATE TABLE source_file(id TEXT PRIMARY KEY,sha256 TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,bytes BLOB NOT NULL,byte_size INTEGER NOT NULL,created_at TEXT NOT NULL,CHECK(length(bytes)=byte_size)) STRICT;
CREATE TABLE import_run(id TEXT PRIMARY KEY REFERENCES operation(id),parser_version TEXT NOT NULL,totals_json TEXT NOT NULL,row_counts_json TEXT NOT NULL,selected_sources_json TEXT NOT NULL) STRICT;
CREATE TABLE import_file(run_id TEXT NOT NULL REFERENCES import_run(id),file_id TEXT NOT NULL REFERENCES source_file(id),sheet_name TEXT NOT NULL,input_mode TEXT NOT NULL,original_run_id TEXT,authoritative_snapshot_hash TEXT NOT NULL,original_name TEXT NOT NULL,header_map_json TEXT NOT NULL,counters_json TEXT NOT NULL,PRIMARY KEY(run_id,file_id,sheet_name)) STRICT;
CREATE TABLE financial_source(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('CASHBOOK_CARD','BANK_CARD','BOOKING')),source_identity TEXT NOT NULL,canonical_json TEXT NOT NULL CHECK(json_valid(canonical_json)),content_hash TEXT NOT NULL,local_date TEXT NOT NULL,occurred_at_utc TEXT,time_precision TEXT NOT NULL,signed_amount_minor INTEGER NOT NULL CHECK(signed_amount_minor!=0 AND abs(signed_amount_minor)<=9000000000000000),currency TEXT NOT NULL CHECK(currency IN ('CZK','EUR')),primary_identifier TEXT NOT NULL,description TEXT,created_at TEXT NOT NULL,UNIQUE(kind,source_identity)) STRICT;
CREATE TABLE cashbook_detail(source_id TEXT PRIMARY KEY REFERENCES financial_source(id),cashbook_number TEXT,invoice_code TEXT NOT NULL,storno_marker INTEGER NOT NULL,payload_json TEXT NOT NULL) STRICT;
CREATE TABLE bank_detail(source_id TEXT PRIMARY KEY REFERENCES financial_source(id),terminal_id TEXT NOT NULL,seq_id TEXT NOT NULL,event_class TEXT NOT NULL,payload_json TEXT NOT NULL,UNIQUE(terminal_id,seq_id,event_class)) STRICT;
CREATE TABLE booking_detail(source_id TEXT PRIMARY KEY REFERENCES financial_source(id),payout_key TEXT NOT NULL,payout_id TEXT NOT NULL,booking_reference TEXT NOT NULL,payload_json TEXT NOT NULL) STRICT;
CREATE TABLE source_occurrence(run_id TEXT NOT NULL REFERENCES import_run(id),file_id TEXT NOT NULL REFERENCES source_file(id),sheet TEXT NOT NULL,row_start INTEGER NOT NULL,row_end INTEGER NOT NULL CHECK(row_end>=row_start),source_id TEXT REFERENCES financial_source(id),disposition TEXT NOT NULL,repair_code TEXT,raw_cells_json TEXT NOT NULL,raw_types_json TEXT NOT NULL,PRIMARY KEY(run_id,file_id,sheet,row_start)) STRICT;
CREATE TABLE work_object(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('SOURCE','GROUP')),source_id TEXT UNIQUE REFERENCES financial_source(id),currency TEXT NOT NULL CHECK(currency IN ('CZK','EUR')),lifecycle TEXT NOT NULL CHECK(lifecycle IN ('ACTIVE','DISSOLVED')),revision INTEGER NOT NULL CHECK(revision>=1),CHECK((type='SOURCE' AND source_id IS NOT NULL) OR (type='GROUP' AND source_id IS NULL))) STRICT;
CREATE TABLE reconciliation_group(object_id TEXT PRIMARY KEY REFERENCES work_object(id),method TEXT NOT NULL,note TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,evidence_json TEXT NOT NULL) STRICT;
CREATE TABLE command(id TEXT PRIMARY KEY,type TEXT NOT NULL,method TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,suppression_before_json TEXT NOT NULL,suppression_after_json TEXT NOT NULL,inverse_json TEXT NOT NULL,expected_revisions_json TEXT NOT NULL,compensates_id TEXT REFERENCES command(id),state TEXT NOT NULL,created_at TEXT NOT NULL,history_position INTEGER NOT NULL,redo_valid INTEGER NOT NULL DEFAULT 1) STRICT;
CREATE TABLE membership(id TEXT PRIMARY KEY,parent_id TEXT NOT NULL REFERENCES reconciliation_group(object_id),child_id TEXT NOT NULL REFERENCES work_object(id),active INTEGER NOT NULL CHECK(active IN(0,1)),created_by_command TEXT NOT NULL REFERENCES command(id),ended_by_command TEXT REFERENCES command(id),created_at TEXT NOT NULL,ended_at TEXT,CHECK(parent_id!=child_id)) STRICT;
CREATE UNIQUE INDEX one_active_parent ON membership(child_id) WHERE active=1;
CREATE INDEX membership_parent_active ON membership(parent_id,active);
CREATE INDEX source_currency_date ON financial_source(currency,local_date,id);
CREATE INDEX source_kind_identity ON financial_source(kind,source_identity);
CREATE INDEX booking_reference_lookup ON booking_detail(booking_reference);
CREATE INDEX bank_sequence_lookup ON bank_detail(terminal_id,seq_id);
CREATE TABLE audit_event(id TEXT PRIMARY KEY,operation_id TEXT REFERENCES operation(id),command_id TEXT REFERENCES command(id),type TEXT NOT NULL,object_refs_json TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,amounts_by_currency_json TEXT NOT NULL,method TEXT NOT NULL,note TEXT,timestamp TEXT NOT NULL) STRICT;
CREATE TABLE auto_suppression(fingerprint TEXT PRIMARY KEY,command_id TEXT NOT NULL REFERENCES command(id),active INTEGER NOT NULL,revision INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL) STRICT;
CREATE TABLE saved_filter(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,scope TEXT NOT NULL,filter_json TEXT NOT NULL,sort_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,revision INTEGER NOT NULL) STRICT;
CREATE TABLE view_state(view_key TEXT PRIMARY KEY,columns_json TEXT NOT NULL,sort_json TEXT NOT NULL,scroll_anchor_id TEXT,revision INTEGER NOT NULL) STRICT;
CREATE TABLE work_selection(object_id TEXT PRIMARY KEY REFERENCES work_object(id),expected_revision INTEGER NOT NULL,position INTEGER NOT NULL UNIQUE) STRICT;
CREATE TABLE import_diagnostic(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES import_run(id),file_id TEXT REFERENCES source_file(id),input_mode TEXT NOT NULL,sheet TEXT,row_start INTEGER,row_end INTEGER,severity TEXT NOT NULL,code TEXT NOT NULL,column_key TEXT,raw_value_json TEXT,identity TEXT,source_id TEXT,field_diff_json TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TABLE helper_context(id TEXT PRIMARY KEY,status TEXT NOT NULL CHECK(status IN ('CURRENT','RETIRED')),credential_revision INTEGER NOT NULL UNIQUE,created_at TEXT NOT NULL,retired_at TEXT) STRICT;
CREATE UNIQUE INDEX one_current_context ON helper_context(status) WHERE status='CURRENT';
CREATE TABLE helper_generation(id TEXT PRIMARY KEY,context_id TEXT NOT NULL REFERENCES helper_context(id),credential_revision INTEGER NOT NULL,kind TEXT NOT NULL,predecessor_id TEXT REFERENCES helper_generation(id),state TEXT NOT NULL,operation_id TEXT NOT NULL REFERENCES operation(id),plan_json TEXT NOT NULL,graph_hash TEXT,evidence_epoch INTEGER,created_at TEXT NOT NULL,sealed_at TEXT,published_at TEXT,UNIQUE(context_id,id)) STRICT;
CREATE TABLE helper_snapshot(id TEXT PRIMARY KEY,context_id TEXT NOT NULL REFERENCES helper_context(id),resource_type TEXT NOT NULL,external_id TEXT NOT NULL,projection_kind TEXT NOT NULL,request_shape_hash TEXT NOT NULL,endpoint_template TEXT NOT NULL,payload_json TEXT NOT NULL,content_hash TEXT NOT NULL,fetched_at TEXT NOT NULL,sync_run_id TEXT NOT NULL,UNIQUE(context_id,resource_type,external_id,projection_kind,request_shape_hash,content_hash),UNIQUE(context_id,id)) STRICT;
CREATE TABLE helper_observation(id TEXT PRIMARY KEY,context_id TEXT NOT NULL,generation_id TEXT NOT NULL,operation_id TEXT NOT NULL,block_key TEXT NOT NULL,request_index INTEGER NOT NULL,snapshot_id TEXT NOT NULL,observed_at TEXT NOT NULL,origin TEXT NOT NULL,FOREIGN KEY(context_id,generation_id) REFERENCES helper_generation(context_id,id),FOREIGN KEY(context_id,snapshot_id) REFERENCES helper_snapshot(context_id,id)) STRICT;
CREATE TABLE helper_current(context_id TEXT NOT NULL,generation_id TEXT NOT NULL,resource_type TEXT NOT NULL,external_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,revision INTEGER NOT NULL,active INTEGER NOT NULL,complete INTEGER NOT NULL,root_observed INTEGER NOT NULL,inactive_reason TEXT,local_search_text TEXT NOT NULL,PRIMARY KEY(context_id,generation_id,resource_type,external_id),FOREIGN KEY(context_id,generation_id) REFERENCES helper_generation(context_id,id),FOREIGN KEY(context_id,snapshot_id) REFERENCES helper_snapshot(context_id,id)) STRICT;
CREATE TABLE helper_link(id TEXT PRIMARY KEY,context_id TEXT NOT NULL,generation_id TEXT NOT NULL,from_type TEXT NOT NULL,from_id TEXT NOT NULL,relation TEXT NOT NULL,to_type TEXT NOT NULL,to_id TEXT NOT NULL,active INTEGER NOT NULL,complete INTEGER NOT NULL,snapshot_id TEXT NOT NULL,UNIQUE(context_id,generation_id,from_type,from_id,relation,to_type,to_id),FOREIGN KEY(context_id,generation_id,from_type,from_id) REFERENCES helper_current(context_id,generation_id,resource_type,external_id),FOREIGN KEY(context_id,generation_id,to_type,to_id) REFERENCES helper_current(context_id,generation_id,resource_type,external_id),FOREIGN KEY(context_id,snapshot_id) REFERENCES helper_snapshot(context_id,id)) STRICT;
CREATE TABLE helper_reference(id TEXT PRIMARY KEY,context_id TEXT NOT NULL,generation_id TEXT NOT NULL,reservation_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,candidate TEXT,label TEXT,start_offset INTEGER,end_offset INTEGER,parser_version TEXT NOT NULL,status TEXT NOT NULL,FOREIGN KEY(context_id,generation_id) REFERENCES helper_generation(context_id,id),FOREIGN KEY(context_id,snapshot_id) REFERENCES helper_snapshot(context_id,id)) STRICT;
CREATE TABLE helper_override(context_id TEXT NOT NULL REFERENCES helper_context(id),reservation_id TEXT NOT NULL,candidate TEXT,candidate_set_hash TEXT NOT NULL,accepted INTEGER NOT NULL,active INTEGER NOT NULL,command_id TEXT NOT NULL REFERENCES command(id),revision INTEGER NOT NULL,PRIMARY KEY(context_id,reservation_id),CHECK(accepted=0 OR candidate IS NOT NULL)) STRICT;
CREATE TABLE sync_coverage(context_id TEXT NOT NULL,generation_id TEXT NOT NULL,resource_type TEXT NOT NULL,range_start TEXT NOT NULL,range_end TEXT NOT NULL,successful_run_id TEXT NOT NULL,completed_at TEXT NOT NULL,complete INTEGER NOT NULL,PRIMARY KEY(context_id,generation_id,resource_type,range_start,range_end),FOREIGN KEY(context_id,generation_id) REFERENCES helper_generation(context_id,id)) STRICT;
CREATE TABLE helper_state(id INTEGER PRIMARY KEY CHECK(id=1),context_id TEXT NOT NULL REFERENCES helper_context(id),published_generation_id TEXT,status TEXT NOT NULL,previous_status TEXT,evidence_epoch INTEGER NOT NULL,credential_revision INTEGER NOT NULL,revision INTEGER NOT NULL,operation_id TEXT,planned_scope_json TEXT NOT NULL,last_full_success_at TEXT,failure_code TEXT,FOREIGN KEY(context_id,published_generation_id) REFERENCES helper_generation(context_id,id)) STRICT;
CREATE TABLE api_compatibility_run(id TEXT PRIMARY KEY REFERENCES operation(id),context_id TEXT NOT NULL REFERENCES helper_context(id),helper_generation_id TEXT,wire_contract_id TEXT NOT NULL,app_build TEXT NOT NULL,credential_revision INTEGER NOT NULL,range_start TEXT NOT NULL,range_end TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT) STRICT;
CREATE TABLE api_compatibility_endpoint(run_id TEXT NOT NULL REFERENCES api_compatibility_run(id),endpoint_template TEXT NOT NULL,state TEXT NOT NULL,response_count INTEGER NOT NULL,item_count INTEGER NOT NULL,status_codes_json TEXT NOT NULL,response_hashes_json TEXT NOT NULL,field_types_json TEXT NOT NULL,error_codes_json TEXT NOT NULL,PRIMARY KEY(run_id,endpoint_template)) STRICT;
CREATE TABLE group_history(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES reconciliation_group(object_id),command_id TEXT NOT NULL REFERENCES command(id),evidence_json TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TRIGGER current_helper_context BEFORE UPDATE OF context_id ON helper_state BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM helper_context WHERE id=NEW.context_id AND status='CURRENT') THEN RAISE(ABORT,'CONTEXT_NOT_CURRENT') END;
END;
CREATE TRIGGER helper_link_guard BEFORE INSERT ON helper_link WHEN NEW.active=1 BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM helper_current a JOIN helper_current b ON b.context_id=a.context_id AND b.generation_id=a.generation_id WHERE a.context_id=NEW.context_id AND a.generation_id=NEW.generation_id AND a.resource_type=NEW.from_type AND a.external_id=NEW.from_id AND b.resource_type=NEW.to_type AND b.external_id=NEW.to_id AND a.active=1 AND a.complete=1 AND b.active=1 AND b.complete=1) THEN RAISE(ABORT,'HELPER_EDGE_INCOMPLETE') END;
END;
CREATE TRIGGER published_generation_immutable BEFORE UPDATE ON helper_generation WHEN OLD.state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'GENERATION_IMMUTABLE'); END;
CREATE TRIGGER published_generation_no_delete BEFORE DELETE ON helper_generation WHEN OLD.state='PUBLISHED' BEGIN SELECT RAISE(ABORT,'GENERATION_IMMUTABLE'); END;
CREATE TRIGGER generation_publish_guard BEFORE UPDATE OF state ON helper_generation WHEN NEW.state IN ('SEALED','PUBLISHED') BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM helper_context WHERE id=NEW.context_id AND status='CURRENT' AND credential_revision=NEW.credential_revision) THEN RAISE(ABORT,'API_CONTEXT_CHANGED') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM helper_current WHERE context_id=NEW.context_id AND generation_id=NEW.id AND active=1 AND complete=0) THEN RAISE(ABORT,'HELPER_INCOMPLETE') END;
 SELECT CASE WHEN (SELECT count(DISTINCT resource_type) FROM sync_coverage WHERE context_id=NEW.context_id AND generation_id=NEW.id AND complete=1 AND resource_type IN ('invoice','reservation'))!=2 THEN RAISE(ABORT,'COVERAGE_INCOMPLETE') END;
END;
